def parse_nested_parens(paren_string: str) -> List[int]:
    def count_parens(parentheses):
        nesting_level = 0
        open_parens = deque()
        for p in parentheses:
            if p == '(':
                open_parens.append(p)
                nesting_level += 1
            elif p == ')':
                if open_parens:
                    open_parens.pop()
                    nesting_level -= 1
                else:
                    raise ValueError("Mismatched parentheses")
        return nesting_level

    parsed_strings = paren_string.split()
    result = [count_parens(parentheses) for parentheses in parsed_strings]
    return result
