from datetime import datetime

def valid_date(date):
    try:
        # Check if the date string is not empty
        if not date:
            return False

        # Check if the date is in the format 'mm-dd-yyyy'
        if not re.match(r'^([01]?[0-9]-[012]?[0-9]-[0-9]{4}$', date):
            return False

        # Convert the date string to a datetime object
        date_obj = datetime.strptime(date, '%m-%d-%Y')

        # Check if the month is valid (1-12)
        if date_obj.month < 1 or date_obj.month > 12:
            return False

        # Check if the day is valid based on the month
        if date_obj.month in [1, 3, 5, 7, 8, 10, 12]:
            if date_obj.day < 1 or date_obj.day > 31:
                return False
        elif date_obj.month in [4, 6, 9, 11]:
            if date_obj.day < 1 or date_obj.day > 30:
                return False
        else:  # For February
            if date_obj.day < 1 or date_obj.day > 28:  # Assuming non-leap year
                return False
            if date_obj.year % 400 == 0 or (date_obj.year % 100 != 0 and date_obj.year % 4 == 0):
                # If it's a leap year, allow 29 days in February
                if date_obj.day > 29:
                    return False

        # If all checks pass, return True
        return True
    except ValueError:
        # If the date string can't be converted to datetime, return False
        return False
```

