    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def intersection(interval1, interval2):
    start1, end1 = interval1
    start2, end2 = interval2

    if max(start1, end1) < min(start2, end2):
        return "NO"

    if max(start1, end2) < min(start1, end1):
        return "NO"

    length_of_intersection = min(end1, end2) - max(start1, start2) + 1

    if length_of_intersection == 0:
        return "NO"

    return "YES" if is_prime(length_of_intersection) else "NO"
```

This function first checks if the given intervals overlap and if the overlap is empty. If so, it returns "NO". If the intervals do overlap, it calculates the length of the overlap and checks if it's 0. If it is, it returns "NO". Finally, it checks if the length of the overlap is a prime number and returns "YES" if it is, "NO" otherwise.

