from itertools import combinations

def is_equal_to_sum_even(n):
    def is_even(num):
        return num % 2 == 0

    def find_combinations(num, target):
        return list(combinations(range(2, num+1), r=4)) if target <= num else []

    if n < 4 or not is_even(n):
        return False

    combinations_list = find_combinations(n, n)

    for combo in combinations_list:
        total = sum(combo)
        if total == n:
            return True
    return False
```

